-- Employee IDs are generated by the database: EMP-00001, EMP-00002, ...
CREATE SEQUENCE "employee_code_seq" START 1;

-- Continue after the highest existing EMP-<number> code so legacy rows never collide.
SELECT setval(
  'employee_code_seq',
  COALESCE(MAX(substring("employeeCode" from '^EMP-([0-9]+)$')::bigint), 0) + 1,
  false
) FROM "Employee";
